 UserVO user(RoleEnum role,String code){var a=users.saveAndFlush(UserAccount.builder().username(term+code).password("synthetic-hash").realName("Same Name").role(role).department("Dept").teacherCode(code).authorizedMajors("SE").build());return UserVO.builder().id(a.getId()).username(a.getUsername()).realName(a.getRealName()).role(role).department("Dept").teacherCode(code).authorizedMajors("SE").build();}
 Course course(String type,String major,String dept){return courses.saveAndFlush(Course.builder().courseCode(UUID.randomUUID().toString()).courseName("Synthetic, \"course\"\n=SAFE").department(dept).majorCode(major).courseType(type).credits(1d).hours(8).build());}
 CourseOffering offering(Course c,String t){return offerings.saveAndFlush(CourseOffering.builder().course(c).academicTerm(t).teacherName("Same Name").teacherCode("T1").className("Synthetic Class").studentCount(1).status("IN_PROGRESS").build());}
 void as(UserVO u){AuthContext.setCurrentUser(u);}
 @AfterEach void clear(){AuthContext.clear();}
 QualityStatisticsService.Filter filter(){return new QualityStatisticsService.Filter(term,null,null,null,false);}
 SupervisionEvaluation approved(CourseOffering o,String tags){return evals.saveAndFlush(SupervisionEvaluation.builder().offering(o).evaluateDate("2026-10-11").listenTopic("Synthetic").supervisorName("Hidden Reviewer").supervisorUserId(supervisor.getId()).status("APPROVED_PENDING").reviewedBy(director.getId()).reviewedAt(LocalDateTime.now().minusHours(2)).publishTime(LocalDateTime.now().plusDays(1)).scoreAttitude(10d).scoreContent(10d).scoreMethod(10d).scoreEffect(10d).totalScore(40d).templateVersionId(templateId).weightSnapshot("{\"attitude\":25,\"content\":25,\"method\":25,\"effect\":25}").problemTagsJson(tags).problemClassificationVersion("synthetic-v1").build());}
 void open(SupervisionEvaluation e){e.setRecordVersion(evals.findById(e.getId()).orElseThrow().getRecordVersion());e.setPublishTime(LocalDateTime.now().minusSeconds(1));evals.saveAndFlush(e);}
 EvaluationTemplateService.Input input(Long revision,Long based){return new EvaluationTemplateService.Input(revision,"Synthetic","Classroom","Four dimensions",new BigDecimal("25"),new BigDecimal("25"),new BigDecimal("25"),new BigDecimal("25"),based);}
 EvaluationSubmitDTO draft(CourseOffering o){return EvaluationSubmitDTO.builder().offeringId(o.getId()).templateVersionId(templateId).isDraft(true).scoreAttitude(0d).scoreContent(0d).scoreMethod(0d).scoreEffect(0d).suggestions("One suggestion").build();}
 Advice addAdvice(SupervisionEvaluation e)throws Exception{as(supervisor);return advice.receive(e.getId(),new AdviceService.AdviceInput(null,null,"Separate suggestion",json.readTree("[]"),List.of("P2")));}
 CourseResource resource(Course c,String name){String filename=UUID.randomUUID()+".pdf";try{var root=com.classroom.ai.config.UploadPaths.resolveResources("../runtime/sprint3-test/uploads");Files.createDirectories(root);try(var pdf=new org.apache.pdfbox.pdmodel.PDDocument()){pdf.addPage(new org.apache.pdfbox.pdmodel.PDPage());pdf.save(root.resolve(filename).toFile());}}catch(Exception ex){throw new RuntimeException(ex);}return CourseResource.builder().course(c).chapter("Ch1").resourceName(name).fileType("PDF").fileUrl("/uploads/resources/"+filename).tag("理论").isPublic(true).build();}
 List<Boolean> race(UserVO u,Callable<?> work)throws Exception{var barrier=new CyclicBarrier(2);var pool=Executors.newFixedThreadPool(2);try{var tasks=new ArrayList<Future<Boolean>>();for(int i=0;i<2;i++)tasks.add(pool.submit(()->{as(u);try{barrier.await();work.call();return true;}catch(Exception ex){return false;}finally{AuthContext.clear();}}));return List.of(tasks.get(0).get(20,TimeUnit.SECONDS),tasks.get(1).get(20,TimeUnit.SECONDS));}finally{pool.shutdownNow();}}
