  as(director);var r=versions.attach(resource(c1,"In flight"),null,null);as(other);var ticket=files.createTicket(r.getId(),other);var read=new CountDownLatch(1);var revoked=new CountDownLatch(1);var once=new java.util.concurrent.atomic.AtomicBoolean();
  org.mockito.Mockito.doAnswer(inv->{long epoch=(long)inv.callRealMethod();if(once.compareAndSet(false,true)){read.countDown();if(!revoked.await(10,TimeUnit.SECONDS))throw new IllegalStateException("test timeout");}return epoch;}).when(access).epoch(org.mockito.ArgumentMatchers.any());
  var pool=Executors.newSingleThreadExecutor();try{var preview=pool.submit(()->{as(other);try{return files.preview(ticket);}finally{AuthContext.clear();}});assertTrue(read.await(10,TimeUnit.SECONDS));as(director);versions.sharing(r,false);revoked.countDown();var failure=assertThrows(ExecutionException.class,()->preview.get(10,TimeUnit.SECONDS));assertInstanceOf(com.classroom.ai.common.exception.ForbiddenException.class,failure.getCause());}finally{revoked.countDown();pool.shutdownNow();org.mockito.Mockito.reset(access);}
